package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="spms_calibration_decision",uniqueConstraints=@UniqueConstraint(name="uk_spms_calibration_decision",columnNames={"agency_id","calibration_case_id","employee_no"}))public class PerformanceCalibrationDecision extends RspAuditedEntity{public enum Decision{APPROVE,REJECT,ABSTAIN}@Column(name="calibration_case_id",nullable=false,length=36)private String calibrationCaseId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Decision decision;@Column(nullable=false,length=2000)private String rationale;@Column(name="decided_at",nullable=false)private Instant decidedAt;protected PerformanceCalibrationDecision(){}public PerformanceCalibrationDecision(String a,String c,String e,Decision d,String rationale,Instant at){super(a);calibrationCaseId=requiredText(c,"calibrationCaseId");employeeNo=requiredText(e,"employeeNo");decision=d;this.rationale=requiredText(rationale,"rationale");decidedAt=at;}public Decision getDecision(){return decision;}public String getEmployeeNo(){return employeeNo;}public Instant getDecidedAt(){return decidedAt;}public String getRationale(){return rationale;}}
